Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public class Fg {
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
  [DllImport("user32.dll")] public static extern bool BringWindowToTop(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, IntPtr pid);
  [DllImport("user32.dll")] public static extern bool AttachThreadInput(uint a, uint b, bool attach);
  [DllImport("kernel32.dll")] public static extern uint GetCurrentThreadId();
  [DllImport("user32.dll")] public static extern bool SetWindowPos(IntPtr hWnd, IntPtr after, int x, int y, int cx, int cy, uint flags);
  public static void Focus(IntPtr h) {
    IntPtr fg = GetForegroundWindow();
    uint fgThread = GetWindowThreadProcessId(fg, IntPtr.Zero);
    uint thisThread = GetCurrentThreadId();
    AttachThreadInput(thisThread, fgThread, true);
    ShowWindow(h, 9);
    SetWindowPos(h, IntPtr.Zero, 80, 40, 1400, 900, 0x0040);
    BringWindowToTop(h);
    SetForegroundWindow(h);
    AttachThreadInput(thisThread, fgThread, false);
  }
}
'@
$p = Get-Process -Id 39196 -ErrorAction SilentlyContinue
if (-not $p) { Get-Process msedge | Where-Object MainWindowTitle | Format-List Id, MainWindowTitle, MainWindowHandle; exit 1 }
Write-Output "handle $($p.MainWindowHandle) title $($p.MainWindowTitle)"
[Fg]::Focus($p.MainWindowHandle)
Start-Sleep -Milliseconds 400
$fg = [Fg]::GetForegroundWindow()
Write-Output "foreground $fg"

if (-not ('Fg' -as [type])) {
