Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public class Top {
  [DllImport("user32.dll")] public static extern bool SetWindowPos(IntPtr hWnd, IntPtr after, int x, int y, int cx, int cy, uint flags);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
  public static readonly IntPtr TOPMOST = new IntPtr(-1);
  public static readonly IntPtr NOTOPMOST = new IntPtr(-2);
}
'@ -ErrorAction SilentlyContinue
$p = Get-Process -Id 38260
[Top]::ShowWindow($p.MainWindowHandle, 3) | Out-Null
[Top]::SetWindowPos($p.MainWindowHandle, [Top]::TOPMOST, 0, 0, 0, 0, 0x0043) | Out-Null
[Top]::SetForegroundWindow($p.MainWindowHandle) | Out-Null
Start-Sleep -Milliseconds 300
[Top]::SetWindowPos($p.MainWindowHandle, [Top]::NOTOPMOST, 0, 0, 0, 0, 0x0043) | Out-Null
Write-Output "raised $($p.MainWindowTitle)"

